1	export type Cell = [number, number];
2	
3	// --- Living population: how membership of the living set is decided ---
4	
5	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
6	  return x === otherX && y === otherY;
7	}
8	
9	function isLiving(cell: Cell, livingCells: Cell[]): boolean {
10	  return livingCells.some((other) => isSameCell(cell, other));
11	}
12	
13	// --- Neighbourhood topology: which cells are adjacent on the unbounded grid ---
14	
15	function neighboursOf([x, y]: Cell): Cell[] {
16	  const offsets = [-1, 0, 1];
17	  return offsets.flatMap((dx) =>
18	    offsets
19	      .filter((dy) => !(dx === 0 && dy === 0))
20	      .map((dy): Cell => [x + dx, y + dy]),
21	  );
22	}
23	
24	function livingNeighbourCount(cell: Cell, livingCells: Cell[]): number {
25	  return neighboursOf(cell).filter((neighbour) =>
26	    isLiving(neighbour, livingCells),
27	  ).length;
28	}
29	
30	// --- Vitality policy: how a living neighbour count decides life ---
31	
32	const MIN_NEIGHBOURS_TO_SURVIVE = 2;
33	const MAX_NEIGHBOURS_TO_SURVIVE = 3;
34	
35	function survivesWith(livingNeighbours: number): boolean {
36	  return (
37	    livingNeighbours >= MIN_NEIGHBOURS_TO_SURVIVE &&
38	    livingNeighbours <= MAX_NEIGHBOURS_TO_SURVIVE
39	  );
40	}
41	
42	const NEIGHBOURS_TO_REPRODUCE = 3;
43	
44	function isBornWith(livingNeighbours: number): boolean {
45	  return livingNeighbours === NEIGHBOURS_TO_REPRODUCE;
46	}
47	
48	// --- Generation orchestration ---
49	
50	// Only dead cells touching a living cell can be born, so the infinite plane
51	// never has to be enumerated.
52	function deadNeighboursOf(livingCells: Cell[]): Cell[] {
53	  return livingCells
54	    .flatMap(neighboursOf)
55	    .filter((cell) => !isLiving(cell, livingCells));
56	}
57	
58	export function nextGeneration(livingCells: Cell[]): Cell[] {
59	  const survivors = livingCells.filter((cell) =>
60	    survivesWith(livingNeighbourCount(cell, livingCells)),
61	  );
62	  const births = deadNeighboursOf(livingCells).filter((cell) =>
63	    isBornWith(livingNeighbourCount(cell, livingCells)),
64	  );
65	  return [...survivors, ...births];
66	}
